    # For each k, we find the max A such that 5^A <= (12A+1)^k.
    for k in range(1, 11):
        A = 1
        while 5**A <= (12*A + 1)**k:
            A += 1
        A -= 1

        # Search for a_1 <= a_2 <= ... <= a_k in [1, A]
        def search(start_a, current_a_list, current_X_list):
            if len(current_a_list) == k:
